TWO_CHAR = {"==", "!=", "<=", ">=", "->"}
ONE_CHAR = set("+-*/<>=(){},;")
LETTERS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
DIGITS = set("0123456789")
SPACES = set(" \t\r\n")


def tokens(src: str) -> list[str]:
    result = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c in SPACES:
            i += 1
        elif c in LETTERS:
            j = i + 1
            while j < n and (src[j] in LETTERS or src[j] in DIGITS):
                j += 1
            result.append(src[i:j])
            i = j
        elif c in DIGITS:
            j = i + 1
            while j < n and src[j] in DIGITS:
                j += 1
            result.append(src[i:j])
            i = j
        elif c == '"':
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError("unterminated string")
                if src[j] == "\\":
                    j += 2
                    continue
                if src[j] == '"':
                    break
                j += 1
            result.append(src[i:j + 1])
            i = j + 1
        elif i + 1 < n and src[i:i + 2] in TWO_CHAR:
            result.append(src[i:i + 2])
            i += 2
        elif c in ONE_CHAR:
            result.append(c)
            i += 1
        else:
            raise ValueError("unexpected " + c)
    return result
